-- 에코디교회 문서보관: 교회 정관 원본(2024.01.01 제정, 구글문서 '에코디교회정관240121')을 04로 등록하고, 2026 초안은 개정안(참고)으로 분리
INSERT OR IGNORE INTO church_documents (id,bundle,bundle_url,title,category,doc_year,gdoc_url,hwpx_url,note,sort_order,created_by,created_at,updated_at)
 SELECT 'cdoc-2027-selfreliance-04a',bundle,bundle_url,'교회 정관 개정안(참고 · 미의결)',category,'2026',gdoc_url,hwpx_url,'2026.11 작성 초안(에코디 정신·특별의결·회계분리 보강). 제출본은 04 원본 정관',41,'claude','2026-11-23T15:00:00Z','2026-11-23T15:00:00Z' FROM church_documents WHERE id='cdoc-2027-selfreliance-04';
